CREATE TABLE notification_preferences(tenant_id uuid NOT NULL,user_id uuid NOT NULL,push_enabled boolean NOT NULL DEFAULT false,attendance boolean NOT NULL DEFAULT true,grades boolean NOT NULL DEFAULT true,finance boolean NOT NULL DEFAULT true,schedule boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id),FOREIGN KEY(tenant_id,user_id) REFERENCES tenant_memberships(tenant_id,user_id));
CREATE TABLE device_push_tokens(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),family_id uuid NOT NULL,token_hash char(64) NOT NULL UNIQUE,token_encrypted text NOT NULL,platform varchar(10) NOT NULL CHECK(platform IN ('android','ios')),status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REVOKED','INVALID')));
CREATE INDEX push_device_scope_idx ON device_push_tokens(user_id,family_id,status);
CREATE TABLE notifications(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,recipient_user_id uuid NOT NULL,recipient_role "Role" NOT NULL,subject_student_id uuid,event_id uuid NOT NULL REFERENCES outbox_events(id),type varchar(80) NOT NULL,entity_type varchar(30) NOT NULL,entity_id uuid NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,recipient_user_id) REFERENCES tenant_memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,subject_student_id) REFERENCES student_profiles(tenant_id,id));
CREATE UNIQUE INDEX notification_event_recipient_unique ON notifications(event_id,recipient_user_id,recipient_role,subject_student_id) NULLS NOT DISTINCT;
CREATE INDEX notification_recipient_idx ON notifications(tenant_id,recipient_user_id,recipient_role,created_at DESC);
CREATE TABLE notification_deliveries(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,notification_id uuid NOT NULL,device_id uuid NOT NULL REFERENCES device_push_tokens(id),status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENDING','ACCEPTED','SENT','INVALID','UNKNOWN','FAILED','NOT_CONFIGURED','SUPPRESSED')),attempts integer NOT NULL DEFAULT 0,provider_ref varchar(150),last_attempt_at timestamptz,UNIQUE(notification_id,device_id),FOREIGN KEY(tenant_id,notification_id) REFERENCES notifications(tenant_id,id));
